    document.body.style.overflow = "hidden";

    const shapes = gsap.utils.toArray(".reveal-shape");

    const tl = gsap.timeline({
      onComplete: () => {
        document.body.style.overflow = "";
        onComplete();
      },
    });

    tl.set(".reveal-shape", {
      opacity: 0,
      scale: 0,
      transformOrigin: "center",
    })
